import React, { useState, useEffect } from "react";

function ProductForm({ api, onProductSaved, globalSettings }) {

  const createInitialState = () => ({
    nome: "",
    preco_compra: "",
    preco_venda: "",
    peso: "",
    iof_percent: globalSettings.iof_percent || "",
    taxa_dolar: globalSettings.taxa_dolar || "",
  });

  const [form, setForm] = useState(createInitialState());
  const [moedaCompra, setMoedaCompra] = useState("USD");

  useEffect(() => {
    setForm(f => ({
      ...f,
      iof_percent: globalSettings.iof_percent,
      taxa_dolar: globalSettings.taxa_dolar
    }));
  }, [globalSettings]);

  const handleChange = (e) => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    try {
      let precoCompraEmUSD = parseFloat(form.preco_compra);
      const taxaDolar = parseFloat(form.taxa_dolar);

      if (moedaCompra === "BRL") {
        if (!taxaDolar || taxaDolar === 0) {
          alert("A 'Cotação do Dólar' deve ser maior que zero para converter o preço de BRL para USD.");
          return;
        }
        precoCompraEmUSD = precoCompraEmUSD / taxaDolar;
      }

      const dataToSend = {
        ...form,
        preco_compra: precoCompraEmUSD,
        preco_venda: parseFloat(form.preco_venda),
        peso: parseFloat(form.peso),
        iof_percent: parseFloat(form.iof_percent),
        taxa_dolar: taxaDolar,
      };

      await api.post("/produtos", dataToSend);
      alert("Produto cadastrado!");
      setForm(createInitialState());
      setMoedaCompra("USD");
      onProductSaved();

    } catch (error) {
      const errorMsg = error.response?.data?.erro || "Erro ao salvar produto.";
      alert(errorMsg);
    }
  };

  return (
    <div>
      <h2>Cadastrar Produto</h2>
      <form onSubmit={handleSubmit}>

        {/* Nome */}
        <div className="input-group">
          <label htmlFor="nome">Nome</label>
          <input id="nome" name="nome" placeholder="Nome do produto" value={form.nome} onChange={handleChange} required />
        </div>

        {/* Preço Compra + Seletor */}
        <div className="input-group">
          <label htmlFor="preco_compra">Preço Compra</label>
          <input
            id="preco_compra"
            name="preco_compra"
            type="number"
            step="0.01"
            placeholder={`Valor em ${moedaCompra}`}
            value={form.preco_compra}
            onChange={handleChange}
            required
          />
          <select value={moedaCompra} onChange={(e) => setMoedaCompra(e.target.value)}>
            <option value="USD">USD ($)</option>
            <option value="BRL">BRL (R$)</option>
          </select>
        </div>

        {/* Preço Venda */}
        <div className="input-group">
          <label htmlFor="preco_venda">Preço Venda (BRL)</label>
          <input id="preco_venda" name="preco_venda" type="number" step="0.01" placeholder="Ex: 4000.00" value={form.preco_venda} onChange={handleChange} required />
        </div>

        {/* Peso */}
        <div className="input-group">
          <label htmlFor="peso">Peso (kg)</label>
          <input id="peso" name="peso" type="number" step="0.01" placeholder="Ex: 0.6" value={form.peso} onChange={handleChange} required />
        </div>

        {/* IOF */}
        <div className="input-group">
          <label htmlFor="form_iof">IOF (%)</label>
          <input
            id="form_iof"
            name="iof_percent"
            type="number"
            step="0.01"
            placeholder="IOF (%)"
            value={form.iof_percent}
            onChange={handleChange}
            required
          />
        </div>

        {/* Dólar */}
        <div className="input-group">
          <label htmlFor="form_dolar">Cotação Dólar (R$)</label>
          <input
            id="form_dolar"
            name="taxa_dolar"
            type="number"
            step="0.01"
            placeholder="Cotação Dólar (R$)"
            value={form.taxa_dolar}
            onChange={handleChange}
            required
          />
        </div>

        {/* Botão */}
        <div className="input-group">
          {/* Label "fantasma" para alinhar o botão */}
          <label style={{ visibility: 'hidden' }}>Salvar</label>
          <button type="submit">Salvar</button>
        </div>

      </form>
    </div>
  );
}

export default ProductForm;
